import os
from composio import ComposioToolSet, App, Action

def main():
    with open('/logs/trial_id', 'r') as f:
        trial_id = f.read().strip()

    channel_name = f"topic-test-{trial_id}".lower()
    print("Channel Name:", channel_name)

    toolset = ComposioToolSet(entity_id="zealt-user01")

    # create channel
    try:
        res = toolset.execute_action(
            action=Action.SLACK_CONVERSATIONS_CREATE,
            params={"name": channel_name}
        )
        print("Create Channel Response:", res)
        channel_id = res.get('data', {}).get('channel', {}).get('id')
    except Exception as e:
        print("Error creating:", e)
        channel_id = None

    if not channel_id:
        print("Searching for channel...")
        res_list = toolset.execute_action(
            action=Action.SLACK_CONVERSATIONS_LIST,
            params={}
        )
        channels = res_list.get('data', {}).get('channels', [])
        for c in channels:
            if c.get('name') == channel_name:
                channel_id = c.get('id')
                break

    print("Channel ID:", channel_id)

    if channel_id:
        topic = f"Topic for trial {trial_id}"
        print("Setting topic:", topic)
        res_topic = toolset.execute_action(
            action=Action.SLACK_CONVERSATIONS_SET_TOPIC,
            params={"channel": channel_id, "topic": topic}
        )
        print("Update Topic Response:", res_topic)
    else:
        print("Channel not found.")

if __name__ == "__main__":
    main()

