import os
from composio import Composio

def main():
    with open('/logs/trial_id', 'r') as f:
        trial_id = f.read().strip()

    channel_name = f"topic-test-{trial_id}".lower()
    print("Channel Name:", channel_name)

    client = Composio()
    session = client.tool_router.create(user_id="zealt-user01")

    # create channel
    try:
        res = session.execute("SLACK_CREATE_CHANNEL", arguments={"name": channel_name})
        print("Create Channel Response:", res.data)
        channel_id = res.data.get('channel', {}).get('id') if res.data else None
    except Exception as e:
        print("Error creating:", e)
        channel_id = None

    if not channel_id:
        print("Searching for channel...")
        try:
            res_list = session.execute("SLACK_LIST_ALL_CHANNELS", arguments={"limit": 1000})
            channels = res_list.data.get('channels', []) if res_list.data else []
            for c in channels:
                if c.get('name') == channel_name:
                    channel_id = c.get('id')
                    break
        except Exception as e:
            print("Error listing:", e)

    print("Channel ID:", channel_id)

    if channel_id:
        topic = f"Topic for trial {trial_id}"
        print("Setting topic:", topic)
        try:
            res_topic = session.execute("SLACK_SET_THE_TOPIC_OF_A_CONVERSATION", arguments={"channel": channel_id, "topic": topic})
            print("Update Topic Response:", res_topic.data)
        except Exception as e:
            print("Error setting topic:", e)
    else:
        print("Channel not found.")

if __name__ == "__main__":
    main()

